      => RangeLessThan(Key(first, second, third, fourth, fifth, high));

  /// <summary>Reads a key of the layout.</summary>
  /// <exception cref="ArgumentException">The key is not of the layout.</exception>
  /// <exception cref="InvalidCastException">An element has another type.</exception>
  /// <exception cref="OverflowException">A type cannot hold its element's value exactly.</exception>
  public (T1, T2, T3, T4, T5, T6) Decode(ReadOnlySpan<byte> key)
  {
    var reader = Elements(key);
    var elements = (Next<T1>(ref reader, 0), Next<T2>(ref reader, 1), Next<T3>(ref reader, 2), Next<T4>(ref reader, 3),
        Next<T5>(ref reader, 4), Next<T6>(ref reader, 5));
    End(ref reader);
    return elements;
  }

  /// <summary>Reads a key of the layout, as <see cref="Decode"/> does, but returns false where it throws.</summary>
  /// <returns>
  /// False if the key is not of the layout, an element has another type, a type cannot hold its element's value
  /// exactly, or a string element's bytes are not valid UTF-8.
  /// </returns>
  public bool TryDecode(ReadOnlySpan<byte> key, out (T1, T2, T3, T4, T5, T6) elements)
  {
    elements = default;
    if (TryElements(key, out var reader) && TryNext(ref reader, 0, out elements.Item1) &&
        TryNext(ref reader, 1, out elements.Item2) && TryNext(ref reader, 2, out elements.Item3) &&
        TryNext(ref reader, 3, out elements.Item4) && TryNext(ref reader, 4, out elements.Item5) &&
        TryNext(ref reader, 5, out elements.Item6) && TryEnd(ref reader))
      return true;
    elements = default;
    return false;
  }
}

/// <summary>A layout of composite keys of a prefix and seven elements.</summary>
[SuppressMessage("Design", "CA1005", Justification = "A layout has a type for each element, as a tuple does.")]
public sealed class CompositeKeyLayout<T1, T2, T3, T4, T5, T6, T7> : CompositeKeyLayout
{
  /// <summary>A layout of keys that start with a prefix and go on with an element of each type, in the orders given.</summary>
  /// <exception cref="ArgumentException">The prefix is not composite key elements.</exception>
  /// <exception cref="ArgumentOutOfRangeException">An order is not one of <see cref="CompositeKeyOrder"/>.</exception>
  /// <exception cref="NotSupportedException">Composite keys do not support a type, or it is a <see cref="Descending{T}"/>.</exception>
  public CompositeKeyLayout(ReadOnlySpan<byte> prefix,
      CompositeKeyOrder first = CompositeKeyOrder.Ascending, CompositeKeyOrder second = CompositeKeyOrder.Ascending,
      CompositeKeyOrder third = CompositeKeyOrder.Ascending, CompositeKeyOrder fourth = CompositeKeyOrder.Ascending,
      CompositeKeyOrder fifth = CompositeKeyOrder.Ascending, CompositeKeyOrder sixth = CompositeKeyOrder.Ascending,
      CompositeKeyOrder seventh = CompositeKeyOrder.Ascending)
      : base(prefix, [first, second, third, fourth, fifth, sixth, seventh])
  {
    Check<T1>();
    Check<T2>();
    Check<T3>();
    Check<T4>();
    Check<T5>();
    Check<T6>();
    Check<T7>();
  }

  /// <summary>Encodes a key of the layout.</summary>
  public byte[] Create(T1 first, T2 second, T3 third, T4 fourth, T5 fifth, T6 sixth, T7 seventh)
      => Key(first, second, third, fourth, fifth, sixth, seventh);

  /// <summary>The range of the layout's keys that start with an element.</summary>
  public CompositeKeyRange Range(T1 first) => RangeUnder(Key(first));

  /// <summary>The range of the layout's keys that start with elements.</summary>
  public CompositeKeyRange Range(T1 first, T2 second) => RangeUnder(Key(first, second));

  /// <summary>The range of the layout's keys that start with elements.</summary>
  public CompositeKeyRange Range(T1 first, T2 second, T3 third) => RangeUnder(Key(first, second, third));

  /// <summary>The range of the layout's keys that start with elements.</summary>
  public CompositeKeyRange Range(T1 first, T2 second, T3 third, T4 fourth) => RangeUnder(Key(first, second, third, fourth));

  /// <summary>The range of the layout's keys that start with elements.</summary>
  public CompositeKeyRange Range(T1 first, T2 second, T3 third, T4 fourth, T5 fifth)
      => RangeUnder(Key(first, second, third, fourth, fifth));

  /// <summary>The range of the layout's keys that start with elements.</summary>
  public CompositeKeyRange Range(T1 first, T2 second, T3 third, T4 fourth, T5 fifth, T6 sixth)
      => RangeUnder(Key(first, second, third, fourth, fifth, sixth));

  /// <summary>
  /// The range of the layout's keys whose first element is from one value through
  /// another, given in either order, each included or excluded as the bounds say.
  /// </summary>
  /// <exception cref="ArgumentOutOfRangeException">The bounds are not one of <see cref="CompositeKeyBounds"/>.</exception>
  public CompositeKeyRange Between(T1 low, T1 high, CompositeKeyBounds bounds = CompositeKeyBounds.Inclusive)
      => RangeBetween(Key(low), Key(high), bounds);

  /// <summary>
  /// The range of the layout's keys that start with an element and whose next element is from one value through
  /// another, given in either order, each included or excluded as the bounds say.
  /// </summary>
  /// <exception cref="ArgumentOutOfRangeException">The bounds are not one of <see cref="CompositeKeyBounds"/>.</exception>
  public CompositeKeyRange Between(T1 first, T2 low, T2 high, CompositeKeyBounds bounds = CompositeKeyBounds.Inclusive)
      => RangeBetween(Key(first, low), Key(first, high), bounds);

  /// <summary>
