  /// <summary>Reads a key of the layout.</summary>
  /// <exception cref="ArgumentException">The key is not of the layout.</exception>
  /// <exception cref="InvalidCastException">An element has another type.</exception>
  /// <exception cref="OverflowException">A type cannot hold its element's value exactly.</exception>
  public (T1, T2, T3, T4, T5, T6, T7) Decode(ReadOnlySpan<byte> key)
  {
    var reader = Elements(key);
    var elements = (Next<T1>(ref reader, 0), Next<T2>(ref reader, 1), Next<T3>(ref reader, 2), Next<T4>(ref reader, 3),
        Next<T5>(ref reader, 4), Next<T6>(ref reader, 5), Next<T7>(ref reader, 6));
    End(ref reader);
    return elements;
  }

  /// <summary>Reads a key of the layout, as <see cref="Decode"/> does, but returns false where it throws.</summary>
  /// <returns>
  /// False if the key is not of the layout, an element has another type, a type cannot hold its element's value
  /// exactly, or a string element's bytes are not valid UTF-8.
  /// </returns>
  public bool TryDecode(ReadOnlySpan<byte> key, out (T1, T2, T3, T4, T5, T6, T7) elements)
  {
    elements = default;
    if (TryElements(key, out var reader) && TryNext(ref reader, 0, out elements.Item1) &&
        TryNext(ref reader, 1, out elements.Item2) && TryNext(ref reader, 2, out elements.Item3) &&
        TryNext(ref reader, 3, out elements.Item4) && TryNext(ref reader, 4, out elements.Item5) &&
        TryNext(ref reader, 5, out elements.Item6) && TryNext(ref reader, 6, out elements.Item7) &&
        TryEnd(ref reader))
      return true;
    elements = default;
    return false;
  }
}

/// <summary>A layout of composite keys of a prefix and eight elements.</summary>
